urlset:
{%- macro href(file) -%}
    {%- if file.page and file.page.canonical_url -%}
        {{- file.page.canonical_url | e -}}
    {%- elif file.page and file.page.abs_url -%}
        {{- file.page.abs_url | e -}}
    {%- elif file.url == "./" -%}
        {{- config.site_url -}}
    {%- else -%}
        {{- config.site_url ~ file.url -}}
    {%- endif -%}
{%- endmacro -%}

{%- for locale, i18n_files in i18n_alternates.items() %}

{%- for file in i18n_files %}
    {%- if not file.page or file.page.is_link %}
        {%- continue %}
    {%- endif %}

    {#- 1. 원본으로 떨어진 쪽 -#}
    {%- if file.locale != locale %}
        {%- continue %}
    {%- endif %}

    {#-
        Warning! Don't align the XML tags based on the Jinja2 statements.
        It will cause whitespace misalignment in the output.
    #}

        {{ href(file) }}
    {%- if file.page.update_date %}
        {{ file.page.update_date }}
    {%- endif %}
        daily
    {%- set ns = namespace(x_default=none, fallback=none) %}
    {%- for i18n_locale, i18n_file in file.alternates | dictsort %}
        {#- 2. 번역이 실제로 있는 언어만 -#}
        {%- if i18n_file.locale != i18n_locale %}
            {%- continue %}
        {%- endif %}
        {%- if i18n_locale == "en" %}
            {%- set ns.x_default = i18n_file %}
        {%- endif %}
        {%- if i18n_file.localization is none %}
            {%- set ns.fallback = i18n_file %}
        {%- endif %}

    {%- endfor %}
    {%- set x_default = ns.x_default or ns.fallback %}
    {%- if x_default %}

    {%- endif %}

{%- endfor %}
{%- endfor %}
